fn pad2(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 10 {
        host::display::draw_number(x, y, 0, rgb, sc);
        host::display::draw_number(x + sc * 8, y, v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let offs = [-5, 0, 9];
    let total: i32 = t / 60 + 14 * 3600 + 25 * 60;
    let mm: i32 = (total / 60) % 60;
    host::display::clear(0x0a0a10);
    host::display::draw_string(16, 12, "WORLD CLOCK", 0x808080, 1);
    let mut i: i32 = 0;
    while i < 3 {
        let hh: i32 = ((total / 3600 + offs[i]) % 24 + 24) % 24;
        let y: i32 = 50 + i * 70;
        match i {
            0 => {
                host::display::draw_string(16, y, "NYC", 0x80a0ff, 2);
            }
            1 => {
                host::display::draw_string(16, y, "LON", 0x80ffa0, 2);
            }
            _ => {
                host::display::draw_string(16, y, "TYO", 0xffa080, 2);
            }
        }
        pad2(90, y - 6, hh, 0xffffff, 3);
        host::display::fill_rect(146, y + 2, 4, 4, 0xffffff);
        host::display::fill_rect(146, y + 12, 4, 4, 0xffffff);
        pad2(158, y - 6, mm, 0xffffff, 3);
        i = i + 1;
    }
    host::display::draw_string(16, 270, "UTC-5 UTC+0 UTC+9", 0x606060, 1);
    host::display::present();
}
